package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.dto.*;
import com.pet.buscaativa.entities.enums.*;
import com.pet.buscaativa.repositories.*;
import com.pet.buscaativa.services.*;

class CancellationIndicatorsTests extends CancellationRegularizationSupport {
    @Autowired GrupoTerapeuticoService groupService;
    @Autowired SessaoGrupoRepository sessions;
    private void indicators(int misses,ClassificacaoRisco risk,boolean visit){var p=patients.findById(patient.getId()).orElseThrow();assertEquals(misses,p.getCountFaltas());assertEquals(risk,p.getClassificacaoRisco());assertEquals(visit,p.getGatilhoVisitaAcionado());assertFalse(p.getIndicadoresPendentes());}
    private boolean selected() throws Exception {var r=mvc.perform(get("/api/pacientes/busca-ativa").header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse();assertEquals(200,r.getStatus());return java.util.stream.StreamSupport.stream(json.readTree(r.getContentAsString()).spliterator(),false).anyMatch(n->patient.getIdPublico().toString().equals(n.get("idPublico").asText()));}
    @Test void ih02To04TwoAndThreeExplicitCanceledAbsencesUseCanonicalFrequency() throws Exception {long previous=appointments.countBySituacaoAtendimentoAndDataAgendamentoBetween(SituacaoAtendimento.FALTOU,DAY.minusDays(4),DAY);for(int i=3;i>=1;i--){final int days=i;var a=tx(()->seed(patient,professional,SituacaoAtendimento.CANCELADO,DAY.minusDays(days),"08:00"));assertEquals(200,factual(a,FrequenciaAssistencial.FALTOU));assertCanceledFact(a,FrequenciaAssistencial.FALTOU);if(i==2)indicators(2,ClassificacaoRisco.AMARELO,false);}indicators(3,ClassificacaoRisco.VERMELHO,false);assertTrue(selected());assertEquals(previous+3,appointments.countBySituacaoAtendimentoAndDataAgendamentoBetween(SituacaoAtendimento.FALTOU,DAY.minusDays(4),DAY));}
    @Test void ih05And07RegularizedMissedSuccessorTriggersVisitAndCorrectionClearsIt() throws Exception {var a=legitimateRescheduledCancellation();now(DAY.atTime(16,0));long rows=appointments.count();assertEquals(200,factual(a,FrequenciaAssistencial.FALTOU));indicators(2,ClassificacaoRisco.AMARELO,true);assertTrue(selected());var current=appointment(a.getId());assertEquals(200,correct(professional,current,FrequenciaAssistencial.PRESENTE));indicators(0,ClassificacaoRisco.VERDE,false);assertFalse(selected());assertEquals(rows,appointments.count());assertCanceledFact(a,FrequenciaAssistencial.PRESENTE);assertTrue(appointment(a.getId()).isRemarcacaoAposFalta());assertEquals(DAY,patients.findById(patient.getId()).orElseThrow().getDataUltimaPresenca());}
    @Test void ih01And06HistoricalCanceledPresenceResetsLaterSequenceAndUsesAttendanceDay() throws Exception {var earlier=tx(()->seed(patient,professional,SituacaoAtendimento.FALTOU,DAY.minusDays(10),"08:00"));var a=canceled(false);var later=tx(()->seed(patient,professional,SituacaoAtendimento.FALTOU,DAY.minusDays(2),"08:00"));assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));indicators(1,ClassificacaoRisco.VERDE,false);assertEquals(a.getDataAgendamento(),patients.findById(patient.getId()).orElseThrow().getDataUltimaPresenca());}
    @Test void ih08SubsequentEffectiveGroupPresenceSharesTheSameChronology() throws Exception {var a=legitimateRescheduledCancellation();now(DAY.atTime(16,0));assertEquals(200,factual(a,FrequenciaAssistencial.FALTOU));indicators(2,ClassificacaoRisco.AMARELO,true);authenticate();var g=groupService.criarGrupo(new CriarGrupoDTO("Grupo sintético após regularização",professional.getIdPublico(),RecorrenciaGrupo.UNICA,DAY,null,LocalTime.of(15,30),List.of(patient.getIdPublico())));var s=tx(()->sessions.findAll().stream().filter(x->x.getGrupo().getId().equals(g.id())).findFirst().orElseThrow());var dto=new ConfirmarOcorrenciaGrupoDTO(true,List.of(new FrequenciaParticipanteGrupoDTO(patient.getIdPublico(),StatusPresencaGrupo.PRESENTE)),null,s.getVersion());var r=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/grupos/sessoes/"+s.getId()+"/confirmacao-ocorrencia").header("Authorization","Bearer "+tokens.gerarToken(professional)).contentType("application/json").content(json.writeValueAsString(dto))).andReturn().getResponse();assertEquals(200,r.getStatus(),r.getContentAsString());indicators(0,ClassificacaoRisco.VERDE,false);assertFalse(selected());}
    @Test void canonicalPresenceIsExposedInPatientHistoryAndAppointmentListDespiteCanceledProjection() throws Exception {var a=canceled(false);assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));var r=mvc.perform(get("/api/pacientes/"+patient.getIdPublico()+"/agendamentos").header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse();assertEquals(200,r.getStatus());var n=java.util.stream.StreamSupport.stream(json.readTree(r.getContentAsString()).spliterator(),false).filter(x->x.get("id").asLong()==a.getId()).findFirst().orElseThrow();assertEquals("CANCELADO",n.get("situacaoAtendimento").asText());assertEquals("PRESENTE",n.get("frequenciaAssistencial").asText());assertFalse(n.get("ocupaVaga").asBoolean());r=mvc.perform(get("/api/pacientes/"+patient.getIdPublico()+"/historico").header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse();assertEquals(200,r.getStatus());assertEquals(1,json.readTree(r.getContentAsString()).get("totalPresencas").asInt());}
}
